", "t": [["terminal", "{"command":"cd \"D:/Projects/local_ai/strata-lab/runs/work/hermes/jsondiff-1794053379\" && python - <<'EOF'\nfrom jsondiff import diff\ncases = [\n    (([1], [True]), ['~ $[0]: 1 -> true']),\n    (([1], [1.0]), ['~ $[0]: 1 -> 1.0']),\n    ((None, None), []),\n    (({}, {}), []),\n    (([], [1, 2]), ['+ $[0]: 1', '+ $[1]: 2']),\n    (([1, 2], []), ['- $[0]: 1', '- $[1]: 2']),\n    (({\"a\": {\"b\": 1}}, {\"a\": [1]}), ['~ $.a: {\"b\": 1} -> [1]']),\n    (({\"a\": {\"b\": 1}}, {\"a\": {\"b\": 1, \"c\": None}}), ['+ $.a.c: null']),\n    ((1, 1), []),\n    ((\"x\", \"x\"), []),\n    ((True, 1), ['~ $: true -> 1']),\n    (({\"ab\": 1, \"a\": {\"c\": 1}}, {\"a\": {\"c\": 2}}), ['~ $.a.c: 1 -> 2', '- $.ab: 1']),\n    (({\"k\": {\"b\": [1,{\"z\":1,\"y\":2}], \"a\": 2}}, {\"k\": {\"a\": 2, \"b\": [1,{\"y\":2,\"z\":1}]}}), []),\n]\nok = True\nfor (a, b), want in cases:\n    got = diff(a, b)\n    status = \"ok \" if got == want else \"FAIL\"\n    if got != want: ok = False\n    print(status, repr(a), \"->\", repr(b), \"=>\", got)\nprint(\"ALL OK\" if ok else \"MISMATCHES\")\nEOF"}"]]}
